#include <stdio.h>

/* teste do desafio contagem-final — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   A captura do stdout acontece DENTRO do teste: freopen manda o stdout
   para o arquivo temporario, o teste chama a funcao do aluno e le o
   arquivo de volta, linha a linha. Nunca ha fclose de stdout — so
   fflush (C11 7.21.4). */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void contagemFinal(void);

SM_TEST(a_contagem_de_dez_a_um_e_o_fogo) {
    /* captura: o stdout vira o arquivo sm_saida_1.tmp */
    freopen("sm_saida_1.tmp", "w", stdout);
    contagemFinal();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a linha do 10", linha, "10\n",
              "a contagem comeca no 10, o valor com que o contador nasceu");
    fgets(linha, 80, f);
    checa_str("a linha do 9", linha, "9\n",
              "o passo -- tira um do contador a cada volta");
    fgets(linha, 80, f);
    checa_str("a linha do 8", linha, "8\n",
              "a terceira volta ja esta dois abaixo do inicio");
    fgets(linha, 80, f);
    checa_str("a linha do 7", linha, "7\n",
              "o mesmo printf, na quarta volta");
    fgets(linha, 80, f);
    checa_str("a linha do 6", linha, "6\n",
              "o mesmo printf, na quinta volta");
    fgets(linha, 80, f);
    checa_str("a linha do 5", linha, "5\n",
              "o mesmo printf, na sexta volta");
    fgets(linha, 80, f);
    checa_str("a linha do 4", linha, "4\n",
              "o mesmo printf, na setima volta");
    fgets(linha, 80, f);
    checa_str("a linha do 3", linha, "3\n",
              "o mesmo printf, na oitava volta");
    fgets(linha, 80, f);
    checa_str("a linha do 2", linha, "2\n",
              "o mesmo printf, na nona volta");
    fgets(linha, 80, f);
    checa_str("a linha do 1", linha, "1\n",
              "a condicao i >= 1 deixa o proprio 1 entrar: ele e a ultima volta");

    /* a decima primeira linha e a palavra, e ela vem UMA vez, depois do laco */
    fgets(linha, 80, f);
    checa_str("a linha do FOGO", linha, "FOGO\n",
              "o printf do FOGO esta FORA das chaves: sai uma vez, no fim");

    /* a saida TERMINA no FOGO — buffer NOVO com sentinel e um fgets a mais */
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "sao onze linhas: dez numeros e o FOGO, nada depois");
    fclose(f);
}

